content:
:root {
  --primary-color: #4f46e5;
  --primary-hover: #4338ca;
  --bg-gradient: linear-gradient(135deg, #f3f4f6 0%, #e5e7eb 100%);
  --card-bg: #ffffff;
  --text-main: #1f2937;
  --text-muted: #6b7280;
  --border-color: #e5e7eb;
  --accent-color: #10b981;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background: var(--bg-gradient);
  color: var(--text-main);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
}

.app-container {
  width: 100%;
  max-width: 600px;
  padding: 1rem;
  margin: 0 auto;
}

.game-card {
  background: var(--card-bg);
  border-radius: 1rem;
  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.05), 0 8px 10px -6px rgba(0, 0, 0, 0.05);
  padding: 2.5rem 2rem;
  text-align: center;
  border: 1px solid var(--border-color);
  transition: all 0.3s ease;
}

.title {
  font-size: 2rem;
  font-weight: 800;
  color: var(--text-main);
  margin-bottom: 1.5rem;
  letter-spacing: -0.025em;
}

.timer {
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--primary-color);
  background: rgba(79, 70, 229, 0.1);
  padding: 0.5rem 1rem;
  border-radius: 9999px;
  display: inline-block;
  margin-bottom: 1rem;
}

.score {
  font-size: 1rem;
  font-weight: 500;
  color: var(--text-muted);
  margin-bottom: 2rem;
}

.word-display {
  background: #f9fafb;
  border: 2px solid var(--border-color);
  border-radius: 0.75rem;
  padding: 2rem 1rem;
  margin-bottom: 2rem;
}

.japanese-text {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text-main);
  margin-bottom: 0.5rem;
}

.romaji-text {
  font-size: 1.25rem;
  font-weight: 500;
  color: var(--text-muted);
  letter-spacing: 0.1em;
  font-family: monospace;
}

.input-area {
  width: 100%;
  padding: 1rem 1.25rem;
  font-size: 1.25rem;
  border: 2px solid var(--border-color);
  border-radius: 0.75rem;
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
  text-align: center;
  font-family: monospace;
  margin-bottom: 1.5rem;
}

.input-area:focus {
  border-color: var(--primary-color);
  box-shadow: 0 0 0 4px rgba(79, 70, 229, 0.1);
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.875rem 2rem;
  font-size: 1rem;
  font-weight: 600;
  border-radius: 0.75rem;
  border: none;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
}

.btn:active {
  transform: scale(0.98);
}

.btn-primary {
  background-color: var(--primary-color);
  color: #ffffff;
  width: 100%;
}

.btn-primary:hover {
  background-color: var(--primary-hover);
}

.result-screen {
  animation: fadeIn 0.4s ease-out;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1rem;
  margin: 2rem 0;
}

.stat-item {
  background: #f9fafb;
  border: 1px solid var(--border-color);
  padding: 1.25rem;
  border-radius: 0.75rem;
  text-align: center;
}

.stat-item .label {
  font-size: 0.875rem;
  color: var(--text-muted);
  margin-bottom: 0.5rem;
}

.stat-item .value {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--primary-color);
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (max-width: 480px) {
  .game-card {
    padding: 1.5rem 1rem;
  }

  .title {
    font-size: 1.5rem;
  }

  .stats-grid {
    grid-template-columns: 1fr;
  }
}

export interface WordItem {
  id: string;
  japanese: string;
  romaji: string;
}

export type GameState = 'start' | 'playing' | 'result';

import { useState, useEffect, useRef } from 'react';
import { WordItem, GameState } from '../types';

const INITIAL_WORDS: WordItem[] = [
  { id: '1', japanese: '日本語', romaji: 'nihongo' },
  { id: '2', japanese: 'タイピングゲーム', romaji: 'taipingugeemu' },
  { id: '3', japanese: 'プログラミング', romaji: 'puroguramingu' },
  { id: '4', japanese: 'リアクト', romaji: 'riakuto' },
  { id: '5', japanese: 'コンポーネント', romaji: 'konpoenento' },
  { id: '6', japanese: 'インターネット', romaji: 'intaanetto' },
  { id: '7', japanese: 'キーボード', romaji: 'kiiboodo' },
  { id: '8', japanese: 'アプリケーション', romaji: 'apurikeeshon' },
  { id: '9', japanese: 'オープンソース', romaji: 'oopunsoosu' },
  { id: '10', japanese: 'デベロッパー', romaji: 'deberoppaa' },
];

const shuffleArray = (array: WordItem[]): WordItem[] => {
  const shuffled = [...array];
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }
  return shuffled;
};

// 代替入力（si/shi, tu/tsu等）に対応するための正規化関数
const normalizeRomaji = (str: string): string => {
  return str
    .replace(/shi/g, 'si')
    .replace(/chi/g, 'ti')
    .replace(/tsu/g, 'tu')
    .replace(/fu/g, 'hu')
    .replace(/ji/g, 'zi')
    .replace(/sha/g, 'sya')
    .replace(/shu/g, 'syu')
    .replace(/sho/g, 'syo')
    .replace(/cha/g, 'tya')
    .replace(/chu/g, 'tyu')
    .replace(/cho/g, 'tyo')
    .replace(/ja/g, 'zya')
    .replace(/ju/g, 'zyu')
    .replace(/jo/g, 'zyo');
};

export default function TypingGame() {
  const [gameState, setGameState] = useState<GameState>('start');
  const [words, setWords] = useState<WordItem[]>(INITIAL_WORDS);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [inputVal, setInputVal] = useState('');
  const [timeLeft, setTimeLeft] = useState(60);
  const [score, setScore] = useState(0);
  const [totalTypedChars, setTotalTypedChars] = useState(0);
  const [missCount, setMissCount] = useState(0);
  const [isError, setIsError] = useState(false);

  const inputRef = useRef<HTMLInputElement>(null);

  const currentWord = words[currentIndex % words.length];

  // ゲーム開始
  const startGame = () => {
    setGameState('playing');
    setTimeLeft(60);
    setScore(0);
    setTotalTypedChars(0);
    setMissCount(0);
    setIsError(false);
    setWords(shuffleArray(INITIAL_WORDS));
    setCurrentIndex(0);
    setInputVal('');
    setTimeout(() => {
      inputRef.current?.focus();
    }, 50);
  };

  // タイマー
  useEffect(() => {
    if (gameState !== 'playing') return;

    if (timeLeft <= 0) {
      setGameState('result');
      return;
    }

    const timer = setInterval(() => {
      setTimeLeft((prev) => prev - 1);
    }, 1000);

    return () => clearInterval(timer);
  }, [gameState, timeLeft]);

  // 入力処理（大文字小文字許容・前方一致判定・柔軟なローマ字変換・ミスフィードバック）
  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (gameState !== 'playing') return;
    const val = e.target.value;
    const lowerVal = val.toLowerCase();
    const targetRomaji = currentWord.romaji.toLowerCase();

    const normalizedInput = normalizeRomaji(lowerVal);
    const normalizedTarget = normalizeRomaji(targetRomaji);

    // 前方一致チェック（代替入力対応）
    if (normalizedTarget.startsWith(normalizedInput)) {
      setInputVal(val);
      setIsError(false);

      // 完全一致判定
      if (normalizedInput === normalizedTarget) {
        setScore((prev) => prev + 1);
        setTotalTypedChars((prev) => prev + currentWord.romaji.length);
        setCurrentIndex((prev) => prev + 1);
        setInputVal('');
      }
    } else {
      // ミスタイプ時の処理
      setIsError(true);
      setMissCount((prev) => prev + 1);
      setTimeout(() => {
        setIsError(false);
      }, 300);
    }
  };

  return (
    <div className="game-card">
      {gameState === 'start' && (
        <div>
          <h1 className="title">ローマ字タイピングゲーム</h1>
          <p className="score" style={{ marginBottom: '2rem' }}>
            60秒間で何文字打てるか挑戦しよう！
          </p>
          <button className="btn btn-primary" onClick={startGame}>
            スタート
          </button>
        </div>
      )}

      {gameState === 'playing' && (
        <div>
          <div className="timer">残り時間: {timeLeft}秒</div>
          <div className="score">スコア: {score}問正解 (ミス: {missCount})</div>

          <div className="word-display">
            <div className="japanese-text">{currentWord.japanese}</div>
            <div className="romaji-text">{currentWord.romaji}</div>
          </div>

          <input
            ref={inputRef}
            type="text"
            className="input-area"
            value={inputVal}
            onChange={handleInputChange}
            placeholder="ここにローマ字を入力..."
            style={isError ? { borderColor: '#ef4444', boxDecorationBreak: 'clone', boxShadow: '0 0 0 4px rgba(239, 68, 68, 0.1)' } : {}}
            autoFocus
            autoCapitalize="none"
            autoComplete="off"
            spellCheck="false"
          />

          <button className="btn" onClick={() => setGameState('start')} style={{ background: '#e5e7eb', color: '#374151', width: '100%' }}>
            中断する
          </button>
        </div>
      )}

      {gameState === 'result' && (
        <div className="result-screen">
          <h1 className="title">ゲーム終了！</h1>
          <p className="score">お疲れ様でした！結果はこちらです。</p>

          <div className="stats-grid">
            <div className="stat-item">
              <div className="label">正解数 / ミス数</div>
              <div className="value">{score} 問 / {missCount} 回</div>
            </div>
            <div className="stat-item">
              <div className="label">打った文字数</div>
              <div className="value">{totalTypedChars} 文字</div>
            </div>
          </div>

          <button className="btn btn-primary" onClick={startGame}>
            もう一度プレイする
          </button>
        </div>
      )}
    </div>
  );
}

import TypingGame from './components/TypingGame';
import './index.css';

export default function App() {
  return (
    <div className="app-container">
      <TypingGame />
    </div>
  );
}
